window.__finlexDocLoaded(10170,{"id":10170,"articles":[{"id":1000711,"no":"Overview","heading":"Scope & Statutory / Regulatory Role (Public Summary)","text":"Requires designing and implementing overall responses and tailored audit procedures (tests of controls and substantive procedures) whose nature, timing, and extent directly respond to assessed risks of material misstatement.","seq":0},{"id":1000712,"no":"AS 2301.05–.46","heading":"Tests of Controls, Dual-Purpose Tests & Substantive Responses","text":"• Significant & Fraud Risks (AS 2301.11–.15): Must perform substantive procedures specifically responsive to significant risks, including tests of details.\n• Reliance on Controls (AS 2301.16–.35): Must test operating effectiveness whenever relying on controls to reduce substantive testing (or when substantive procedures alone cannot provide sufficient evidence).\n• No Rotational Control Testing for ICFR: In an integrated audit (AS 2201), key controls MUST be tested EVERY YEAR (unlike ISA 330's 3-year rotation option for non-significant risks).","seq":1},{"id":1000713,"no":"Cross-Framework Comparison","heading":"US vs. International (ISA/OECD/COSO) & China Context","text":"• Key Difference from ISA 330: ISA 330.14 permits relying on prior-year control testing once every 3 years for unchanged non-significant controls; in a SOX 404(b) integrated audit under AS 2201/AS 2301, key controls must be tested annually.","seq":2},{"id":1000714,"no":"Official Access","heading":"Official Regulatory / Statutory Source","text":"Official Source (PCAOB Auditing Standards): https://pcaobus.org/oversight/standards/auditing-standards\nStatus: in_force.","seq":3}]});
